WITH kept_keys AS (SELECT channel FROM orders EXCEPT DISTINCT SELECT channel FROM orders WHERE status != 'SHIPPED'), kept_rows AS (SELECT s.* FROM orders s INNER JOIN kept_keys k ON s.channel = k.channel) SELECT DATE_TRUNC('YEAR', order_date) AS year_start, CASE WHEN shipping_fee >= 42 THEN 'PREMIUM' ELSE 'STANDARD' END AS shipping_fee_tier, COUNT_IF(status = 'CANCELLED') AS cancelled_events, STDDEV_SAMP(amount) AS amount_stddev, STDDEV_SAMP(shipping_fee) AS shipping_fee_stddev, COUNT_IF(channel = 'store') AS store_events FROM kept_rows GROUP BY DATE_TRUNC('YEAR', order_date), CASE WHEN shipping_fee >= 42 THEN 'PREMIUM' ELSE 'STANDARD' END;
